def feats(b):
    g = b.grid
    a = g[0][3] == 2 and g[1][3] == 1
    c = g[1][4] == 2 and g[2][4] == 1
    d = g[1][0] == 2 and g[2][0] == 2
    return int(a) + int(c) + int(d)

def fires(b):
    return feats(b) >= 2

def level(b):
    return [0, 2, 6, 9][feats(b)]

def fires(b):
    return len(b.my_wins) > 0 and not b.my_playable_wins and not b.their_playable_wins

def level(b):
    if not fires(b):
        return 0
    return min(9, 3 + 2 * len(b.my_wins))

def parts(b):
    g = b.grid
    a = g[1][0] == 2 and g[2][0] == 2              # them stacked at col 0 rows 1-2
    c4 = g[0][4] == 1 and g[1][4] == 2 and g[2][4] == 1  # col 4 bottom me/them/me
    c3 = g[0][3] == 2 and g[1][3] == 1              # col 3 bottom them/me
    return a, c4, c3

def fires(b):
    a, c4, c3 = parts(b)
    return c3 and (a or c4)

def level(b):
    a, c4, c3 = parts(b)
    n = int(a) + int(c4) + int(c3)
    if fires(b):
        return 6 + 3 * (n == 3)
    return n

# open diagonal lines (>=2 own stones, no opponent stone) in the lower centre-right
LINES = [
    (1, [(0, 4), (1, 3), (2, 2), (3, 1)]),  # my anti-diagonal through (0,4),(1,3)
    (2, [(0, 3), (1, 4), (2, 5), (3, 6)]),  # their diagonal through (0,3),(1,4)
    (1, [(1, 3), (2, 4), (3, 5), (4, 6)]),  # my diagonal through (1,3),(2,4)
    (1, [(0, 6), (1, 5), (2, 4), (3, 3)]),  # my anti-diagonal through (2,4),(3,3)
    (1, [(1, 3), (2, 2), (3, 1), (4, 0)]),
    (1, [(0, 2), (1, 3), (2, 4), (3, 5)]),
]

def count(b):
    n = 0
    for who, cells in LINES:
        v = [b.grid[r][c] for r, c in cells]
        if v.count(who) >= 2 and v.count(3 - who) == 0:
            n += 1
    return n

def fires(b):
    return count(b) >= 2

def level(b):
    return min(9, 2 * count(b))
